func botDeceptionDecodeOptionalInt64(object map[string]json.RawMessage, key, location string, diagnostics *diag.Diagnostics) int64 {
	raw, ok := object[key]
	if !ok || botDeceptionJSONNull(raw) {
		return 0
	}
	var number json.Number
	if err := json.Unmarshal(raw, &number); err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" "+key+" was not an integer.")
		return 0
	}
	value, err := number.Int64()
	if err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" "+key+" was not an integer.")
		return 0
	}
	return value
}

// DecodeOptionalInt64WithDefault decodes an optional integer item field,
// substituting the reviewed default when the successful GET omits the key or
// returns null. This mirrors the encode path (PlannedOptionalInt64 sends the
// reviewed default when the practitioner omits the field), so state carries the
// reviewed default rather than 0 and a later update does not reuse a stale 0.
func botDeceptionDecodeOptionalInt64WithDefault(object map[string]json.RawMessage, key, location string, defaultValue int64, diagnostics *diag.Diagnostics) int64 {
	raw, ok := object[key]
	if !ok || botDeceptionJSONNull(raw) {
		return defaultValue
	}
	var number json.Number
	if err := json.Unmarshal(raw, &number); err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" "+key+" was not an integer.")
		return 0
	}
	value, err := number.Int64()
	if err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" "+key+" was not an integer.")
		return 0
	}
	return value
}

func botDeceptionDecodeScalars(result client.WAFModuleResult) (botDeceptionScalars, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	scalarsResult := botDeceptionScalars{}

	actionRaw, ok := result.Configs["action"]
	if !ok || botDeceptionJSONNull(actionRaw) {
		diagnostics.AddError("Malformed bot deception result", "The successful API result did not contain a non-null action string.")
	} else {
		var actionValue string
		if err := json.Unmarshal(actionRaw, &actionValue); err != nil || !botDeceptionConfigActionValid(actionValue) {
			diagnostics.AddError("Malformed bot deception result", "The successful API result contained an invalid action.")
		} else {
			scalarsResult.Action = actionValue
		}
	}

	deception_urlRaw, ok := result.Configs["deception_url"]
	if !ok {
		// Missing optional key with a reviewed default: decode to the default
		// so a configured-default value does not perpetual-diff when the
		// backend omits default-valued keys.
		deception_urlDefault := "/url.html"
		scalarsResult.DeceptionURL = &deception_urlDefault
	} else if botDeceptionJSONNull(deception_urlRaw) {
		diagnostics.AddError("Malformed bot deception result", "The successful API result contained null deception_url, which the pinned schema does not mark nullable.")
	} else {
		var deception_urlValue string
		if err := json.Unmarshal(deception_urlRaw, &deception_urlValue); err != nil {
			diagnostics.AddError("Malformed bot deception result", "The successful API result contained an invalid deception_url.")
		} else {
			if utf8.RuneCountInString(deception_urlValue) > 255 {
				diagnostics.AddError("Malformed bot deception result", fmt.Sprintf("The successful API result contained deception_url exceeding %d UTF-8 characters.", 255))
			} else {
				scalarsResult.DeceptionURL = &deception_urlValue
			}
		}
	}

	statusRaw, ok := result.Configs["status"]
	if !ok || botDeceptionJSONNull(statusRaw) {
		diagnostics.AddError("Malformed bot deception result", "The successful API result did not contain a non-null status boolean.")
	} else {
		var statusValue bool
		if err := json.Unmarshal(statusRaw, &statusValue); err != nil {
			diagnostics.AddError("Malformed bot deception result", "The successful API result contained an invalid status.")
		} else {
			scalarsResult.Status = statusValue
		}
	}
	return scalarsResult, diagnostics
}

func botDeceptionDecodeExceptionList(raw json.RawMessage) (botDeceptionExceptionListOwnedList, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(raw) == 0 {
		return botDeceptionExceptionListOwnedList{}, diagnostics
	}
	if botDeceptionJSONNull(raw) {
		diagnostics.AddError("Malformed bot deception result", "The successful API result contained null exception_list instead of an array.")
		return botDeceptionExceptionListOwnedList{}, diagnostics
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed bot deception result", "The successful API result contained a non-array exception_list value.")
		return botDeceptionExceptionListOwnedList{}, diagnostics
	}
	if len(rawItems) > botDeceptionExceptionListMaxItems {
		diagnostics.AddError("Malformed bot deception result", fmt.Sprintf("The successful API result contained more than %d exception_list items.", botDeceptionExceptionListMaxItems))
		return botDeceptionExceptionListOwnedList{}, diagnostics
	}

	items := make([]botDeceptionExceptionListWireItem, 0, len(rawItems))
	seen := make(map[int]struct{}, len(rawItems))
	knownKeys := map[string]struct{}{
		"concatenate_type": {},
		"idx":              {},
		"ip_range":         {},
		"match_target":     {},
		"operator":         {},
		"value":            {},
		"value_check":      {},
		"value_name":       {},
	}
	for position, rawItem := range rawItems {
		location := fmt.Sprintf("exception_list item %d", position+1)
		var object map[string]json.RawMessage
		if err := json.Unmarshal(rawItem, &object); err != nil || object == nil {
			diagnostics.AddError("Malformed bot deception result", location+" was not an object.")
			continue
		}
		unknown := make([]string, 0)
		for key := range object {
			if _, ok := knownKeys[key]; !ok {
				unknown = append(unknown, key)
			}
		}
		sort.Strings(unknown)
		if len(unknown) != 0 {
			diagnostics.AddError("Unknown bot deception item field", location+" contained unsupported keys: "+strings.Join(unknown, ", ")+".")
			continue
		}
		index, ok := botDeceptionDecodeIndex(object["idx"], location, "int", &diagnostics)
		if !ok {
			continue
		}
		if _, duplicate := seen[index]; duplicate {
			diagnostics.AddError("Malformed bot deception result", fmt.Sprintf("%s used duplicate idx %d.", location, index))
			continue
		}
		seen[index] = struct{}{}
		item := botDeceptionExceptionListWireItem{Index: index}
		concatenate_typeValue, ok := botDeceptionDecodeRequiredString(object["concatenate_type"], location+" concatenate_type", &diagnostics)
		if !ok {
			continue
		}
		botDeceptionValidateString(location, " concatenate_type", concatenate_typeValue, 0, 0, &diagnostics)
		if !botDeceptionExceptionListConcatenateTypeValid(concatenate_typeValue) {
			diagnostics.AddError("Malformed bot deception result", location+" concatenate_type was not one of AND, OR.")
		}
		item.ConcatenateType = concatenate_typeValue
		botDeceptionRejectItemNullUnlessNullable(object, "ip_range", false, location, &diagnostics)
		item.IpRange = botDeceptionDecodeOptionalString(object, "ip_range", location, 0, &diagnostics)
		match_targetValue, ok := botDeceptionDecodeRequiredString(object["match_target"], location+" match_target", &diagnostics)
		if !ok {
			continue
		}
		botDeceptionValidateString(location, " match_target", match_targetValue, 0, 0, &diagnostics)
		if !botDeceptionExceptionListMatchTargetValid(match_targetValue) {
			diagnostics.AddError("Malformed bot deception result", location+" match_target was not one of CLIENT_IP, COOKIE, FULL_URL, HOST, PARAMETER, URI.")
		}
		item.MatchTarget = match_targetValue
		operatorValue, ok := botDeceptionDecodeRequiredString(object["operator"], location+" operator", &diagnostics)
		if !ok {
			continue
		}
		botDeceptionValidateString(location, " operator", operatorValue, 0, 0, &diagnostics)
		if !botDeceptionExceptionListOperatorValid(operatorValue) {
			diagnostics.AddError("Malformed bot deception result", location+" operator was not one of EQ, NE, REGEXP_MATCH, STRING_MATCH.")
		}
		item.Operator = operatorValue
		botDeceptionRejectItemNullUnlessNullable(object, "value", false, location, &diagnostics)
		item.Value = botDeceptionDecodeOptionalString(object, "value", location, 0, &diagnostics)
		botDeceptionRejectItemNullUnlessNullable(object, "value_check", false, location, &diagnostics)
		item.ValueCheck = botDeceptionDecodeBoolWithDefault(object, "value_check", location, false, &diagnostics)
		botDeceptionRejectItemNullUnlessNullable(object, "value_name", false, location, &diagnostics)
		item.ValueName = botDeceptionDecodeOptionalString(object, "value_name", location, 0, &diagnostics)
		items = append(items, item)
	}
	if diagnostics.HasError() {
		return botDeceptionExceptionListOwnedList{}, diagnostics
	}
	sort.Slice(items, func(i, j int) bool { return items[i].Index < items[j].Index })
	return botDeceptionExceptionListOwnedList{Set: true, Items: items}, diagnostics
}

func botDeceptionExceptionListWrapperValue(owned botDeceptionExceptionListOwnedList, subItemOwnedMasks map[string][]bool) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if !owned.Set {
		return types.ObjectNull(botDeceptionExceptionListWrapperAttributeTypes), diagnostics
	}
	elements := make([]attr.Value, 0, len(owned.Items))
	for _, item := range owned.Items {
		objectValues := map[string]attr.Value{}
		objectValues["concatenate_type"] = types.StringValue(item.ConcatenateType)
		ip_rangeValue := types.StringNull()
		if item.IpRange != nil {
			ip_rangeValue = types.StringValue(*item.IpRange)
		}
		objectValues["ip_range"] = ip_rangeValue
		objectValues["match_target"] = types.StringValue(item.MatchTarget)
		objectValues["operator"] = types.StringValue(item.Operator)
		valueValue := types.StringNull()
		if item.Value != nil {
			valueValue = types.StringValue(*item.Value)
		}
		objectValues["value"] = valueValue
		objectValues["value_check"] = types.BoolValue(item.ValueCheck)
		value_nameValue := types.StringNull()
		if item.ValueName != nil {
			value_nameValue = types.StringValue(*item.ValueName)
		}
		objectValues["value_name"] = value_nameValue
		object, objectDiagnostics := types.ObjectValue(botDeceptionExceptionListItemAttributeTypes, objectValues)
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: botDeceptionExceptionListItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(botDeceptionExceptionListWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}

func botDeceptionDecodeURLList(raw json.RawMessage) (botDeceptionURLListOwnedList, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(raw) == 0 {
		return botDeceptionURLListOwnedList{}, diagnostics
	}
	if botDeceptionJSONNull(raw) {
		diagnostics.AddError("Malformed bot deception result", "The successful API result contained null url_list instead of an array.")
		return botDeceptionURLListOwnedList{}, diagnostics
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed bot deception result", "The successful API result contained a non-array url_list value.")
		return botDeceptionURLListOwnedList{}, diagnostics
	}
	if len(rawItems) > botDeceptionURLListMaxItems {
		diagnostics.AddError("Malformed bot deception result", fmt.Sprintf("The successful API result contained more than %d url_list items.", botDeceptionURLListMaxItems))
		return botDeceptionURLListOwnedList{}, diagnostics
	}

	items := make([]botDeceptionURLListWireItem, 0, len(rawItems))
	seen := make(map[int]struct{}, len(rawItems))
	knownKeys := map[string]struct{}{
		"idx": {},
		"url": {},
	}
	for position, rawItem := range rawItems {
		location := fmt.Sprintf("url_list item %d", position+1)
		var object map[string]json.RawMessage
		if err := json.Unmarshal(rawItem, &object); err != nil || object == nil {
			diagnostics.AddError("Malformed bot deception result", location+" was not an object.")
			continue
		}
		unknown := make([]string, 0)
		for key := range object {
			if _, ok := knownKeys[key]; !ok {
				unknown = append(unknown, key)
			}
		}
		sort.Strings(unknown)
		if len(unknown) != 0 {
			diagnostics.AddError("Unknown bot deception item field", location+" contained unsupported keys: "+strings.Join(unknown, ", ")+".")
			continue
		}
		index, ok := botDeceptionDecodeIndex(object["idx"], location, "int", &diagnostics)
		if !ok {
			continue
		}
		if _, duplicate := seen[index]; duplicate {
			diagnostics.AddError("Malformed bot deception result", fmt.Sprintf("%s used duplicate idx %d.", location, index))
			continue
		}
		seen[index] = struct{}{}
		item := botDeceptionURLListWireItem{Index: index}
		urlValue, ok := botDeceptionDecodeRequiredString(object["url"], location+" url", &diagnostics)
		if !ok {
			continue
		}
		botDeceptionValidateString(location, " url", urlValue, 0, 255, &diagnostics)
		item.URL = urlValue
		items = append(items, item)
	}
	if diagnostics.HasError() {
		return botDeceptionURLListOwnedList{}, diagnostics
	}
	sort.Slice(items, func(i, j int) bool { return items[i].Index < items[j].Index })
	return botDeceptionURLListOwnedList{Set: true, Items: items}, diagnostics
}

func botDeceptionURLListWrapperValue(owned botDeceptionURLListOwnedList, subItemOwnedMasks map[string][]bool) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if !owned.Set {
		return types.ObjectNull(botDeceptionURLListWrapperAttributeTypes), diagnostics
	}
	elements := make([]attr.Value, 0, len(owned.Items))
	for _, item := range owned.Items {
		objectValues := map[string]attr.Value{}
		objectValues["url"] = types.StringValue(item.URL)
		object, objectDiagnostics := types.ObjectValue(botDeceptionURLListItemAttributeTypes, objectValues)
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: botDeceptionURLListItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(botDeceptionURLListWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}
func botDeceptionDecodeIndex(raw json.RawMessage, location string, idxKind string, diagnostics *diag.Diagnostics) (int, bool) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || botDeceptionJSONNull(trimmed) {
		diagnostics.AddError("Malformed bot deception result", location+" did not contain a non-null integer idx.")
		return 0, false
	}
	if trimmed[0] != '-' && (trimmed[0] < '0' || trimmed[0] > '9') {
		diagnostics.AddError("Malformed bot deception result", location+" contained a non-integer idx.")
		return 0, false
	}
	var number json.Number
	if err := json.Unmarshal(trimmed, &number); err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" contained a non-integer idx.")
		return 0, false
	}
	value64, err := number.Int64()
	if err != nil || value64 <= 0 || int64(int(value64)) != value64 {
		diagnostics.AddError("Malformed bot deception result", location+" contained an idx that was not a positive integer.")
		return 0, false
	}
	return int(value64), true
}
func botDeceptionDecodeRequiredBool(raw json.RawMessage, location string, diagnostics *diag.Diagnostics) (bool, bool) {
	if len(raw) == 0 || botDeceptionJSONNull(raw) {
		diagnostics.AddError("Malformed bot deception result", location+" was missing or null.")
		return false, false
	}
	var value bool
	if err := json.Unmarshal(raw, &value); err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" was not a boolean.")
		return false, false
	}
	return value, true
}
func botDeceptionDecodeRequiredInt64(raw json.RawMessage, location string, diagnostics *diag.Diagnostics) (int64, bool) {
	if len(raw) == 0 || botDeceptionJSONNull(raw) {
		diagnostics.AddError("Malformed bot deception result", location+" was missing or null.")
		return 0, false
	}
	var number json.Number
	if err := json.Unmarshal(raw, &number); err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" was not an integer.")
		return 0, false
	}
	value, err := number.Int64()
	if err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" was not an integer.")
		return 0, false
	}
	return value, true
}

func botDeceptionDecodeRequiredString(raw json.RawMessage, location string, diagnostics *diag.Diagnostics) (string, bool) {
	if len(raw) == 0 || botDeceptionJSONNull(raw) {
		diagnostics.AddError("Malformed bot deception result", location+" was missing or null.")
		return "", false
	}
	var value string
	if err := json.Unmarshal(raw, &value); err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" was not a string.")
		return "", false
	}
	return value, true
}
func botDeceptionDecodeOptionalString(object map[string]json.RawMessage, key, location string, maximum int, diagnostics *diag.Diagnostics) *string {
	raw, ok := object[key]
	if !ok || botDeceptionJSONNull(raw) {
		return nil
	}
	var value string
	if err := json.Unmarshal(raw, &value); err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" "+key+" was not a string or null.")
		return nil
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Malformed bot deception result", fmt.Sprintf("%s %s exceeded %d UTF-8 characters.", location, key, maximum))
		return nil
	}
	return &value
}

// DecodeOptionalStringWithDefault decodes an optional string item field,
// substituting the reviewed default when the successful GET omits the key or
// returns null. This mirrors the encode path (which sends the reviewed default
// when the practitioner omits the field), so the refreshed state carries the
// reviewed default rather than null and a configured-default value does not
// perpetual-diff when the backend omits default-valued keys.
func botDeceptionDecodeOptionalStringWithDefault(object map[string]json.RawMessage, key, location string, maximum int, defaultValue string, diagnostics *diag.Diagnostics) *string {
	raw, ok := object[key]
	if !ok || botDeceptionJSONNull(raw) {
		d := defaultValue
		return &d
	}
	var value string
	if err := json.Unmarshal(raw, &value); err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" "+key+" was not a string or null.")
		return nil
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Malformed bot deception result", fmt.Sprintf("%s %s exceeded %d UTF-8 characters.", location, key, maximum))
		return nil
	}
	return &value
}
func botDeceptionDecodeOptionalBool(object map[string]json.RawMessage, key, location string, diagnostics *diag.Diagnostics) bool {
	raw, ok := object[key]
	if !ok || botDeceptionJSONNull(raw) {
		return false
	}
	var value bool
	if err := json.Unmarshal(raw, &value); err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" "+key+" was not a boolean or null.")
		return false
	}
	return value
}

// botDeceptionDecodeBoolWithDefault decodes an optional boolean item
// field that carries a reviewed provider default. A missing key (omission) or
// an accepted null decodes to the reviewed default (distinct from a required
// field, which rejects a missing key). A present non-boolean value is rejected.
func botDeceptionDecodeBoolWithDefault(object map[string]json.RawMessage, key, location string, defaultValue bool, diagnostics *diag.Diagnostics) bool {
	raw, ok := object[key]
	if !ok || botDeceptionJSONNull(raw) {
		return defaultValue
	}
	var value bool
	if err := json.Unmarshal(raw, &value); err != nil {
		diagnostics.AddError("Malformed bot deception result", location+" "+key+" was not a boolean or null.")
		return defaultValue
	}
	return value
}

func botDeceptionOwnership(ctx context.Context, template bool, ownership wafmodule.OwnershipContext) (botDeceptionOwnershipSet, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if template {
		return botDeceptionOwnershipSet{ExceptionList: false, URLList: false}, diagnostics
	}
	if ownership.Source == wafmodule.OwnershipImported {
		return botDeceptionOwnershipSet{ExceptionList: true, URLList: true}, diagnostics
	}
	configsValue, ownershipDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() || configsValue.IsNull() {
		return botDeceptionOwnershipSet{ExceptionList: false, URLList: false}, diagnostics
	}
	if configsValue.IsUnknown() {
		diagnostics.AddError("Unknown bot deception ownership", "The configs ownership state was unknown while flattening.")
		return botDeceptionOwnershipSet{ExceptionList: false, URLList: false}, diagnostics
	}
	var configs botDeceptionConfigsModel
	diagnostics.Append(configsValue.As(ctx, &configs, basetypes.ObjectAsOptions{})...)
	return botDeceptionOwnershipSet{ExceptionList: !configs.ExceptionList.IsNull(), URLList: !configs.URLList.IsNull()}, diagnostics
}
func botDeceptionValidateString(location, label, value string, minimum, maximum int, diagnostics *diag.Diagnostics) {
	if minimum > 0 && utf8.RuneCountInString(value) < minimum {
		diagnostics.AddError("Invalid bot deception item", fmt.Sprintf("%s%s must be at least %d UTF-8 characters.", location, label, minimum))
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Invalid bot deception item", fmt.Sprintf("%s%s exceeds %d UTF-8 characters.", location, label, maximum))
	}
}
